<main class="section"><div class="section-head"><div><span class="eyebrow">Fristen</span><h1>Zentrale Fristenübersicht</h1></div><a class="btn ghost" href="/admin">Zurück</a></div>
<form method="get" class="filter-bar"><select name="bucket"><option value="">Alle Zeiträume</option><option value="overdue" <?=$filterBucket==='overdue'?'selected':''?>>Überfällig</option><option value="today" <?=$filterBucket==='today'?'selected':''?>>Heute</option><option value="tomorrow" <?=$filterBucket==='tomorrow'?'selected':''?>>Morgen</option><option value="later" <?=$filterBucket==='later'?'selected':''?>>Später</option></select><input name="type" value="<?=App\Core\View::e($filterType)?>" placeholder="Fristtyp"><button class="btn">Filtern</button></form>
<div class="worklist"><?php foreach($items as $i):?><a class="work-row" href="<?=!empty($i['order_id'])?'/admin/auftraege/'.$i['order_id']:'/admin/angebote'?>"><div><b><?=App\Core\View::e($i['type'])?> · <?=App\Core\View::e($i['title'])?></b><span>Fällig <?=date('d.m.Y H:i',strtotime($i['due_at']))?><?php if(!empty($i['grace_at'])):?> · Nachfrist <?=date('d.m.Y H:i',strtotime($i['grace_at']))?><?php endif;?></span></div><strong><?=App\Core\View::e($i['escalation'])?></strong></a><?php endforeach;?><?php if(!$items):?><div class="empty">Keine Fristen für diesen Filter.</div><?php endif;?></div></main>